#include <stdio.h>

typedef struct Node {
    char data;                 // 保存一个字符
    struct Node *next;         // 指向后继结点
} Node;

// 双重循环：逐个比较两个链表的结点地址
Node* findCommon(Node* h1, Node* h2) {
    if (h1 == NULL || h2 == NULL) return NULL;
    for (Node* p = h1->next; p != NULL; p = p->next) {
        for (Node* q = h2->next; q != NULL; q = q->next) {
            if (p == q)        // 比较物理地址，不能比较data字符
                return p;     // 第一次相遇就是共享后缀起点
        }
    }
    return NULL;               // 两链表没有共享结点
}

int main(void) {
    // 后缀i→n→g是两条链表共同使用的同一批结点
    Node g = {'g', NULL}, n = {'n', &g}, i = {'i', &n};
    Node d = {'d', &i}, a = {'a', &d}, o = {'o', &a}, l = {'l', &o};
    Node e = {'e', &i}, b = {'b', &e};
    Node h1 = {0, &l}, h2 = {0, &b}; // 不存数据的头结点
    Node *ans = findCommon(&h1, &h2);
    if (ans) printf("公共后缀起点：%c\n", ans->data);
    else puts("不存在共享后缀");
    return 0;
}

