#include <stdio.h>

typedef struct Node {
    char data;
    struct Node *next;
} Node;

// 不计算头结点，只计算有效字符结点的个数
int length(Node* head) {
    int count = 0;
    for (Node* p = head->next; p != NULL; p = p->next)
        count++;
    return count;
}

// 长链先走长度差，然后两个指针同步移动
Node* findCommon(Node* h1, Node* h2) {
    if (h1 == NULL || h2 == NULL) return NULL;
    int m = length(h1), n = length(h2);
    Node *p = h1->next, *q = h2->next;

    while (m > n) {           // 链表1长，就让p先走
        p = p->next;
        m--;
    }
    while (n > m) {           // 链表2长，就让q先走
        q = q->next;
        n--;
    }

    while (p != NULL && q != NULL) {
        if (p == q) return p; // 同一个地址即共享同一结点
        p = p->next;          // 保持两者距末尾的距离相同
        q = q->next;
    }
    return NULL;
}

int main(void) {
    Node g = {'g', NULL}, n = {'n', &g}, i = {'i', &n};
    Node d = {'d', &i}, a = {'a', &d}, o = {'o', &a}, l = {'l', &o};
    Node e = {'e', &i}, b = {'b', &e};
    Node h1 = {0, &l}, h2 = {0, &b};
    Node *ans = findCommon(&h1, &h2);
    if (ans) printf("公共后缀起点：%c\n", ans->data);
    else puts("不存在共享后缀");
    return 0;
}

