#include <stdio.h>

// 将数组循环左移p位：每次先保存队首，再移动剩余元素
void leftRotate(int R[], int n, int p) {
    if (n <= 1 || p < 0) return; // 空数组或非法位数不处理
    p %= n;                      // 左移n位相当于不动

    for (int i = 0; i < p; i++) {
        int first = R[0];       // 保存原队首，避免数据丢失
        for (int j = 0; j < n - 1; j++) {
            R[j] = R[j + 1];    // 后面的元素向左挪一格
        }
        R[n - 1] = first;       // 原队首放到末尾
    }
}

int main(void) {
    int R[] = {1, 2, 3, 4, 5, 6, 7};
    int n = 7, p = 3;
    leftRotate(R, n, p);
    for (int i = 0; i < n; i++)
        printf("%d%c", R[i], i == n - 1 ? '\n' : ' ');
    return 0;
}

