#include <stdio.h>

// 用左右两个下标交换，使区间原地逆置
void reverse(int R[], int l, int r) {
    while (l < r) {
        int t = R[l];          // 暂存左侧元素，防止被覆盖
        R[l] = R[r];           // 右侧元素放到左边
        R[r] = t;              // 原左侧元素放到右边
        l++;                   // 两个指针向中间靠拢
        r--;
    }
}

// 三次逆置：把 AB 变成 BA，不申请额外数组
void leftRotate(int R[], int n, int p) {
    if (n <= 1 || p < 0) return;
    p %= n;                    // 处理超过一整圈的情况
    if (p == 0) return;
    reverse(R, 0, p - 1);      // A逆置
    reverse(R, p, n - 1);      // B逆置
    reverse(R, 0, n - 1);      // 整体逆置得到BA
}

int main(void) {
    int R[] = {1, 2, 3, 4, 5, 6, 7};
    int n = 7, p = 3;
    leftRotate(R, n, p);
    for (int i = 0; i < n; i++)
        printf("%d%c", R[i], i == n - 1 ? '\n' : ' ');
    return 0;
}

