#include <stdio.h>

// 右移一位：保存末尾，其他元素从右向左移动
void rightRotate(int R[], int n, int p) {
    if (n <= 1 || p < 0) return;
    p %= n;
    for (int i = 0; i < p; i++) {
        int last = R[n - 1];
        for (int j = n - 1; j > 0; j--)
            R[j] = R[j - 1];
        R[0] = last;
    }
}

int main(void) {
    int R[] = {2,4,6,8,10,12,14,16}, n = 8;
    rightRotate(R, n, 3);
    for (int i = 0; i < n; i++)
        printf("%d%c", R[i], i == n - 1 ? '\n' : ' ');
